import{_ as a,o as t,c as s,a8 as n}from"./chunks/framework.CiGKN4gy.js";const p=JSON.parse('{"title":"Reduce bandwidth usage when attacked","description":"","frontmatter":{"title":"Reduce bandwidth usage when attacked","lang":"en"},"headers":[],"relativePath":"practice/reduce-bandwidth-usage-when-attacked.md","filePath":"practice/reduce-bandwidth-usage-when-attacked.md","lastUpdated":1790353258000}'),i={name:"practice/reduce-bandwidth-usage-when-attacked.md"};function d(o,e,r,c,h,l){return t(),s("div",{"data-pagefind-body":!0,"data-pagefind-meta":"base64:JTdCJTIydGl0bGUlMjIlM0ElMjJSZWR1Y2UlMjBiYW5kd2lkdGglMjB1c2FnZSUyMHdoZW4lMjBhdHRhY2tlZCUyMiUyQyUyMmxhbmclMjIlM0ElMjJlbiUyMiUyQyUyMmRhdGUlMjIlM0ExNzkwMzUzMjU4MDAwJTdE"},[...e[0]||(e[0]=[n('<h1 id="reduce-bandwidth-usage-when-attacked" tabindex="-1">Reduce bandwidth usage when attacked <a class="header-anchor" href="#reduce-bandwidth-usage-when-attacked" aria-label="Permalink to &quot;Reduce bandwidth usage when attacked&quot;">​</a></h1><p>When you are under CC attack, the attacker&#39;s IP has been banned by the CC protection, but your upstream and downstream bandwidth is still high. This is because the CC protection returns a status code of 503 and therefore hogs your bandwidth.</p><p>You can use the following configuration to reduce the bandwidth usage.</p><h2 id="for-lts-version" tabindex="-1">For LTS version <a class="header-anchor" href="#for-lts-version" aria-label="Permalink to &quot;For LTS version&quot;">​</a></h2><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">waf_http_status</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cc_deny=444;</span></span></code></pre></div><h2 id="for-current-version" tabindex="-1">For <code>Current</code> version <a class="header-anchor" href="#for-current-version" aria-label="Permalink to &quot;For `Current` version&quot;">​</a></h2><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">waf_action</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cc_deny=444;</span></span></code></pre></div><p>Status code 444 is a non-standard HTTP status code defined by nginx that serves to close the connection and not send any data.</p><div class="danger custom-block"><p class="custom-block-title">WARNING</p><p>If you use status code 444, then your site will look like it doesn&#39;t exist to the user. This is because web site errors usually have HTTP status codes to indicate errors.</p><p>If you visit a website and not only do you not see the page, but also there is no error message, then the website probably does not exist.</p></div>',9)])])}const b=a(i,[["render",d]]);export{p as __pageData,b as default};
